re Date condition"'::jsonb, '"Delete older records"'::jsonb, '"Convert dates to plain text"'::jsonb, '"3-D pie chart with repeated slices"'::jsonb, '"Column chart with labelled subjects"'::jsonb, '"Unlabelled scatter chart"'::jsonb, '"Decorative image"'::jsonb, '"TODAY()"'::jsonb, '"NOW()"'::jsonb, '"DAY()"'::jsonb, '"DATE()"'::jsonb]::jsonb[], ARRAY['2'::jsonb, '0'::jsonb, '1'::jsonb, '0'::jsonb, '1'::jsonb, '1'::jsonb, '0'::jsonb, '1'::jsonb, '1'::jsonb, '1'::jsonb]::jsonb[]);

