VALUES (4400093521010111, ARRAY['"Marks in B2:G2 are out of 100 each. Which formula calculates the percentage correctly?"'::jsonb, '"Which nested IF implements Distinction ≥70%, First ≥60%, Second ≥50%, Pass ≥35%, otherwise Fail?"'::jsonb, '"A copied formula multiplies each student''s amount by a fixed tax rate in B1. Which formula is safe to fill down from D2?"'::jsonb, '"Sum values in F:F only for rows where A equals CE. Which formula is correct?"'::jsonb, '"A percentage formula returns 0.68, displayed as 68%. What is the correct interpretation?"'::jsonb, '"A result formula labels 68% as Distinction although that threshold is 70%. What should be checked first?"'::jsonb, '"Columns A and B must remain visible when scrolling horizontally. Where should the user select before Freeze Panes?"'::jsonb, '"A line chart is requested for six subject categories that are not time points. Which chart is usually easier to interpret?"'::jsonb, '"A table needs sorting by Hire Date and filtering by Designation. Which approach is appropriate?"'::jsonb, '"A formula is copied down, but each row still uses the same candidate''s marks. What should be examined first?"'::jsonb]::jsonb[], ARRAY['"=SUM(B2:G2)/600*100"'::jsonb, '"=AVERAGE(B2:G2)/100"'::jsonb, '"=SUM(B2:G2)/6"'::jsonb, '"=COUNT(B2:G2)*100"'::jsonb, '"=IF(H2>=70%,\"Distinction\",IF(H2>=60%,\"First Class\",IF(H2>=50%,\"Second Class\",IF(H2>=35%,\"Pass\",\"Fail\"))))"'::jsonb, '"=IF(H2>=35%,\"Fail\",\"Pass\")"'::jsonb, '"=SUM(H2)"'::jsonb, '"=COUNT(H2)"'::jsonb, '"=C2*B1"'::jsonb, '"=C2*$B$1"'::jsonb, '"=$C$2*B1"'::jsonb, '"=SUM(C2:B1)"'::jsonb, '"=SUMIF(A:A,\"CE\",F:F)"'::jsonb, '"=COUNTIF(F:F,\"CE\")"'::jsonb, '"=SUM(A:A)"'::jsonb, '"=AVERAGEIF(F:F,\"CE\")"'::jsonb, '"The formula is necessarily wrong"'::jsonb, '"0.68 equals 68%; percentage formatting displays it as 68%"'::jsonb, '"It means 0.68 marks"'::jsonb, '"The worksheet has been filtered"'::jsonb, '"Font colour"'::jsonb, '"Condition order and threshold values in the nested IF"'::jsonb, '"Column width"'::jsonb, '"Whether the sheet has a chart"'::jsonb, '"In the first row only"'::jsonb, '"In C1 or an appropriate cell to the right of column B"'::jsonb, '"In the last used cell only"'::jsonb, '"Inside the formula bar"'::jsonb, '"A bar/column chart with labelled subjects"'::jsonb, '"A line chart implying continuous time"'::jsonb, '"An unlabelled pie chart"'::jsonb, '"A screenshot"'::jsonb, '"Move date cells manually"'::jsonb, '"Use table sort/filter controls on the full records"'::jsonb, '"Delete nonmatching rows permanently"'::jsonb, '"Convert dates to arbitrary text"'::jsonb, '"Whether a row reference was accidentally made absolute"'::jsonb, '"Whether the sheet has a watermark"'::jsonb, '"Whether BCC was filled"'::jsonb, '"Whether browser history is enabled"'::jsonb]::jsonb[], ARRAY['0'::jsonb, '0'::jsonb, '1'::jsonb, '0'::jsonb, '1'::jsonb, '1'::jsonb, '1'::jsonb, '0'::jsonb, '1'::jsonb, '0'::jsonb]::jsonb[]);

